const std::size_t BGM_TABLE_SIZE = sizeof(BGM_TABLE) / sizeof(BGM_TABLE[0]);

const BgmEntry* FindBgmById(std::uint32_t bgmId) noexcept {
    for (std::size_t i = 0; i < BGM_TABLE_SIZE; ++i) {
        if (BGM_TABLE[i].bgmId == bgmId) {
            return &BGM_TABLE[i];
        }
    }
    return nullptr;
}

